214	func writeLocalReviewManifest(ctx context.Context, manifest LocalReviewManifest) error {
215		if len(manifest.Sources) == 0 {
216			return errors.New("review manifest has no sources")
217		}
218		if manifest.Version == 0 {
219			manifest.Version = localReviewManifestVersion
220		}
221		if manifest.CreatedAt.IsZero() {
222			manifest.CreatedAt = time.Now()
223		}
224	
225		dir, err := localReviewManifestDir(ctx)
226		if err != nil {
227			return err
228		}
229		if err := os.MkdirAll(dir, 0o700); err != nil {
230			return fmt.Errorf("create review manifest dir: %w", err)
231		}
232	
233		b, err := json.MarshalIndent(manifest, "", "  ")
234		if err != nil {
235			return fmt.Errorf("encode review manifest: %w", err)
236		}
237		path := filepath.Join(dir, localReviewManifestFilename(manifest))
238		if err := os.WriteFile(path, b, 0o600); err != nil {
239			return fmt.Errorf("write review manifest: %w", err)
240		}
241		return nil
242	}
